CAT = "itpatDivieto"; SEG = "DIV"
# Segnali di divieto e di obbligo. Fonte: DPR 495/1992 (Regolamento) artt. 104, 115-123, 131; CdS art. 38.
Q = [
("Che forma e colori hanno in genere i segnali di divieto?",
 "Rotondi, bordo rosso", ["Rotondi, fondo blu", "Triangolari, bordo rosso", "Quadrati, fondo verde"],
 "Regolamento art. 115: i segnali di divieto sono circolari, in genere con bordo rosso. I segnali rotondi a fondo blu sono invece di obbligo."),
("Che colori hanno i segnali di obbligo generico, come direzione obbligatoria?",
 "Fondo blu, simbolo bianco", ["Fondo bianco, bordo rosso", "Fondo giallo, simbolo nero", "Fondo verde, simbolo bianco"],
 "Regolamento art. 121, comma 2: i segnali di obbligo generico hanno fondo blu e simbolo bianco; quelli di obbligo specifico, come ALT polizia, hanno fondo bianco e bordo rosso."),
("Un cerchio bianco con bordo rosso, senza alcun simbolo all'interno, che cosa vieta?",
 "Il transito a tutti i veicoli", ["Solo la sosta dei veicoli", "Solo l'ingresso dei mezzi pesanti", "Il sorpasso in quel tratto"],
 "Regolamento art. 116: il segnale divieto di transito vieta la circolazione a tutti i veicoli, in entrambi i sensi. Il senso vietato è invece rosso con una barra bianca."),
("Un disco rosso con una barra orizzontale bianca al centro che cosa indica?",
 "Senso vietato", ["Divieto di sosta", "Fine di tutti i divieti", "Strada senza uscita"],
 "Regolamento art. 116: il senso vietato vieta di entrare nella strada da quel lato. Di solito si trova all'uscita delle strade a senso unico."),
("Il segnale divieto di sorpasso, con un'auto rossa accanto a una nera, quali veicoli permette comunque di sorpassare?",
 "Ciclomotori e motocicli", ["Autocarri e autobus", "Tutti i veicoli lenti", "Solo i veicoli in sosta"],
 "Regolamento art. 116, lettera c): il segnale vieta di sorpassare i veicoli a motore, eccetto ciclomotori e motocicli, anche se la manovra resterebbe nella propria metà della carreggiata."),
("Un segnale rotondo di divieto contiene la scritta \"70\". Che cosa prescrive?",
 "Non superare 70 km/h", ["Procedere almeno a 70 km/h", "Tenere 70 m di distanza", "Velocità consigliata di 70 km/h"],
 "Regolamento art. 116, lettera e): il limite massimo di velocità indica la velocità che non si può superare. Il limite minimo è invece su fondo blu, la velocità consigliata su un segnale quadrato."),
("Un segnale rotondo di divieto mostra due auto separate da una freccia verticale e la scritta \"70 m\". Che cosa prescrive?",
 "Distanza minima di 70 m", ["Non superare 70 km/h", "Sorpasso vietato per 70 m", "Sosta vietata per 70 m"],
 "Regolamento art. 116, lettera d): il segnale distanziamento minimo obbligatorio vieta di seguire il veicolo che precede a una distanza inferiore a quella indicata in metri."),
("Un segnale rotondo mostra una trombetta barrata. Che cosa vieta?",
 "L'uso del clacson, salvo pericolo", ["L'uso dell'autoradio ad alto volume", "Il transito alle ambulanze", "La sosta davanti agli ospedali"],
 "Regolamento art. 116, lettera f): il divieto di segnalazioni acustiche proibisce l'uso del clacson, salvo in caso di pericolo immediato."),
("Un segnale rotondo bianco con una sottile banda nera obliqua, senza simboli, che cosa indica?",
 "Fine dei divieti precedenti", ["Inizio di una zona pedonale", "Divieto di transito ai pedoni", "Fine della strada con precedenza"],
 "Regolamento art. 119: il segnale via libera indica il punto in cui cessano le prescrizioni indicate prima, come limiti di velocità e divieti di sorpasso."),
("Dopo il segnale fine limitazione di velocità, quale limite si applica?",
 "Il limite generale della strada", ["Nessun limite di velocità", "Sempre 90 km/h", "Il limite indicato prima del segnale"],
 "Regolamento art. 119, lettera b): il segnale ripristina i limiti generali previsti per quel tipo di strada dall'art. 142 del Codice."),
("Sulla strada di un paese c'è il segnale divieto di sosta senza pannelli integrativi. Quando vale il divieto?",
 "Dalle 8 alle 20", ["Tutto il giorno e la notte", "Solo nei giorni feriali", "Dalle 20 alle 8"],
 "Regolamento art. 120: su strada urbana, senza pannelli, il divieto di sosta vale dalle 8 alle 20. Su strada extraurbana è invece permanente, anche di notte."),
("Fuori dai centri abitati c'è il segnale divieto di sosta senza pannelli. Quando vale?",
 "Sempre, anche di notte", ["Dalle 8 alle 20", "Solo nei giorni festivi", "Solo con pioggia o nebbia"],
 "Regolamento art. 120: sulle strade extraurbane, senza iscrizioni integrative, il divieto di sosta è permanente e vale anche nelle ore notturne."),
("Un segnale rotondo blu con bordo rosso e una croce rossa all'interno che cosa vieta?",
 "Fermata e sosta", ["Solo la sosta lunga", "Solo la fermata breve", "Solo il transito ai camion"],
 "Regolamento art. 120, lettera b): il divieto di fermata vieta in permanenza sosta, fermata e ogni arresto volontario. Il divieto di sosta ha una sola barra rossa."),
("Davanti a un passo carrabile autorizzato, che cosa è vietato?",
 "Sostare, a ogni ora", ["Sostare solo di notte", "Transitare con l'auto", "Fermarsi per la salita di persone"],
 "Regolamento art. 120, lettera e) e CdS art. 158: in corrispondenza del passo carrabile vige in permanenza il divieto di sosta."),
("Il segnale rotondo transito vietato agli autocarri, con la scritta \"3,5 t\", a quali veicoli si applica?",
 "Veicoli merci oltre 3,5 t", ["Tutti i veicoli oltre 3,5 t", "Autobus oltre 3,5 t", "Auto con rimorchio leggero"],
 "Regolamento art. 117, lettera i): il divieto riguarda i veicoli di massa a pieno carico superiore a 3,5 t non adibiti al trasporto di persone; gli autobus non sono compresi."),
("Un segnale rotondo blu mostra una freccia bianca rivolta verso destra. Che cosa prescrive?",
 "Proseguire solo a destra", ["Svolta a destra vietata", "Strada con precedenza a destra", "Parcheggio sulla destra"],
 "Regolamento art. 122: il segnale direzione obbligatoria indica l'unica direzione consentita in quel punto. Le altre direzioni sono vietate."),
("Su un'isola spartitraffico c'è un segnale rotondo blu con una freccia obliqua in basso a destra. Che cosa indica?",
 "Passare a destra dell'ostacolo", ["Svoltare subito a destra", "Passare a sinistra dell'isola", "Uscire dalla strada principale"],
 "Regolamento art. 122, comma 4: il passaggio obbligatorio impone di passare dal lato indicato di un ostacolo, di un salvagente o di un'isola di traffico."),
("Un segnale rotondo blu mostra tre frecce bianche disposte in cerchio. Che cosa prescrive?",
 "Girare nel verso delle frecce", ["Fare inversione di marcia", "Dare precedenza a chi entra da destra", "Parcheggiare in tondo"],
 "Regolamento art. 122, comma 6: il segnale rotatoria obbliga a circolare secondo il verso indicato dalle frecce. È posto sulla soglia della rotatoria."),
("Un segnale rotondo blu riporta la scritta \"30\". Che cosa prescrive?",
 "Procedere almeno a 30 km/h", ["Non superare 30 km/h", "Velocità consigliata di 30 km/h", "Zona con limite di 30 km/h"],
 "Regolamento art. 122, comma 7: il limite minimo di velocità obbliga a non scendere sotto la velocità indicata. I veicoli che non la raggiungono non devono impegnare quella strada."),
("Un segnale rotondo blu mostra una ruota con le catene. Che cosa prescrive?",
 "Catene o gomme invernali", ["Solo le catene montate sulle ruote", "Strada chiusa per neve", "Velocità massima ridotta"],
 "Regolamento art. 122, comma 8: dal punto del segnale è obbligatorio circolare con catene da neve oppure con pneumatici invernali."),
("Un segnale rotondo blu mostra una bicicletta bianca. Che cosa indica?",
 "Pista riservata alle bici", ["Divieto di transito alle bici", "Bici ammesse in carreggiata", "Noleggio di biciclette"],
 "Regolamento art. 122, comma 9: il segnale pista ciclabile indica un percorso riservato ai velocipedi e vietato agli altri veicoli."),
("Un segnale rotondo bianco con bordo rosso porta la scritta \"ALT POLIZIA\". Che cosa si deve fare?",
 "Fermarsi al posto di blocco", ["Rallentare senza fermarsi", "Cedere il passo alla polizia", "Accendere i fari e proseguire"],
 "Regolamento art. 123: ALT polizia è un segnale di obbligo specifico che indica un posto di blocco dove fermarsi è obbligatorio."),
("Un divieto di sorpasso è stato posto prima di un incrocio. Dopo l'incrocio non c'è alcun segnale. Che cosa vale?",
 "Il divieto è finito", ["Il divieto continua", "Vale per 500 m", "Vale solo di notte"],
 "Regolamento art. 104, comma 2: i segnali di divieto e di obbligo devono essere ripetuti dopo ogni intersezione; se non sono ripetuti, la prescrizione non prosegue."),
("Su quale lato della strada si collocano di norma i segnali di prescrizione?",
 "Sul lato destro", ["Sul lato sinistro", "Al centro della strada", "Indifferentemente"],
 "Regolamento art. 104, comma 3: i segnali di prescrizione si pongono sul lato destro; sulle strade a più corsie possono essere ripetuti a sinistra o sopra la carreggiata."),
("Un pannello sotto il divieto di transito riporta \"eccetto\" e il simbolo di un autobus. Che cosa significa?",
 "Gli autobus possono transitare", ["Solo gli autobus non transitano", "Gli autobus devono fermarsi", "Gli autobus hanno precedenza"],
 "Regolamento art. 83, comma 7: il pannello con la parola eccetto concede una deroga alla prescrizione per le categorie indicate."),
("Il cartello di inizio centro abitato, con il nome del paese, che cosa comporta anche senza altri segnali?",
 "Limite di 50 km/h e niente clacson", ["Limite di 30 km/h in tutto il paese", "Divieto di sosta su ogni strada", "Obbligo di luci accese anche di giorno"],
 "Regolamento art. 131, comma 4: il segnale di inizio centro abitato vale anche come limite di velocità urbano e come divieto di segnalazioni acustiche."),
("Un segnale rotondo mostra una moto nera su fondo bianco con bordo rosso. Che cosa vieta?",
 "Il transito dei motocicli", ["Il sorpasso delle moto", "La sosta delle moto", "Il transito delle biciclette"],
 "Regolamento art. 117, lettera e): il segnale transito vietato ai motocicli vieta la circolazione dei motocicli su quella strada."),
("Un segnale rotondo mostra un pedone nero su fondo bianco con bordo rosso. Che cosa indica?",
 "Transito vietato ai pedoni", ["Percorso riservato ai pedoni", "Attraversamento pedonale vicino", "Zona con molti pedoni"],
 "Regolamento art. 117, lettera c): il segnale vieta il transito ai pedoni. Il percorso pedonale ha invece fondo blu e simbolo bianco."),
]
